// mono, trimmed (from just before its attack to -50 dB, with a 2 ms fade), peak-normalised and stored as int16 at
// 44.1 kHz. They follow the firmware's 12 transients and two generated ones as waves 14..35. Generated, do not edit.
const B64C = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const decC = (s) => {
  const u = new Uint8Array(Math.floor(s.replace(/=+$/, '').length * 3 / 4));
  for (let i = 0, o = 0, bits = 0, n = 0; i < s.length && s[i] !== '='; i++) {
    bits = (bits << 6) | B64C.indexOf(s[i]); n += 6;
    if (n >= 8) { n -= 8; u[o++] = (bits >> n) & 0xff; }
  }
  return u.buffer;
};
const CLICK_PCM = new Int16Array(decC(""));
const CLICK_AT = [0, 6034, 7751, 12298, 12734, 14078, 14507, 14910, 15343, 17584, 21086, 23767, 27536, 32372, 32747, 33175, 33606, 34801, 35224, 37070, 37499, 37923], CLICK_LEN = [6034, 1717, 4547, 436, 1344, 429, 403, 433, 2241, 3502, 2681, 3769, 4836, 375, 428, 431, 1195, 423, 1846, 429, 424, 633];
